    <div class="plt-pack-raw" style="display:none;">$1</div>

    <!-- 折叠标签行:───── ✦ PLUTO SUMMARY ───── ☀ -->
    <div class="plt-pack-bar">
        <div class="plt-pack-toggle" onclick="pltPackToggle(this)">
            <span class="plt-line"></span>
            <span class="plt-icon">✦</span>
            <span class="plt-title">Pluto Summary</span>
            <span class="plt-line"></span>
        </div>
        <div class="plt-theme-switch" onclick="pltPackTheme(event, this)">☀</div>
    </div>

    <!-- UI 渲染区(默认折叠) -->
    <div class="plt-pack-interface" style="display:none;">
        <div class="plt-pack-tabs"></div>
        <div class="plt-pack-viewport"></div>
        <div class="plt-pack-foot"></div>
    </div>

    <script>
        // ── 日/夜切换 ──
        window.pltPackTheme = function(event, btn) {
            event.stopPropagation();
            var wrap = btn.closest('.plt-pack-wrapper');
            wrap.classList.toggle('day-mode');
            btn.innerHTML = wrap.classList.contains('day-mode') ? '☾' : '☀';
        };

        // ── 展开 / 折叠 + 首次解析 ──
        window.pltPackToggle = function(btn) {
            var wrap = btn.closest('.plt-pack-wrapper');
            var ui = wrap.querySelector('.plt-pack-interface');
            var icon = btn.querySelector('.plt-icon');

            if (ui.style.display === 'none') {
                ui.style.display = 'block';
                icon.innerText = '✧';
            } else {
                ui.style.display = 'none';
                icon.innerText = '✦';
                return;
            }

            // 已解析过则直接返回,避免重复渲染
            if (wrap.dataset.parsed === 'true') return;

            var rawHtml = wrap.querySelector('.plt-pack-raw').innerHTML;
            var temp = document.createElement('div');
            temp.innerHTML = rawHtml;

            var tabsBox = wrap.querySelector('.plt-pack-tabs');
            var viewBox = wrap.querySelector('.plt-pack-viewport');
            var isFirst = true;

            var targets = ['Snapshot', 'abstract', 'Todo', 'seeds', 'Events'];

            targets.forEach(function(tag) {
                var content = '';
                // 方法A:DOM 直接取
                var el = temp.querySelector(tag);
                if (el) {
                    content = el.innerHTML;
                } else {
                    // 方法B:DOM 被转义破坏时走正则容错
                    var regex = new RegExp('<' + tag + '>([\\s\\S]*?)<\\/' + tag + '>', 'i');
                    var match = rawHtml.match(regex);
                    if (match) content = match[1];
                }

                if (content && content.trim() !== '') {
                    var tBtn = document.createElement('div');
                    tBtn.className = 'plt-pack-btn' + (isFirst ? ' active' : '');
                    tBtn.innerText = tag.toUpperCase();

                    var pnl = document.createElement('div');
                    pnl.className = 'plt-pack-panel' + (isFirst ? ' active' : '');
                    pnl.innerHTML = content.trim();

                    tBtn.onclick = function(e) {
                        e.stopPropagation();
                        tabsBox.querySelectorAll('.plt-pack-btn').forEach(function(b) { b.classList.remove('active'); });
                        viewBox.querySelectorAll('.plt-pack-panel').forEach(function(p) { p.classList.remove('active'); });
                        tBtn.classList.add('active');
                        pnl.classList.add('active');
                    };

                    tabsBox.appendChild(tBtn);
                    viewBox.appendChild(pnl);
                    isFirst = false;
                }
            });

            wrap.dataset.parsed = 'true';
        };
    </script>
</div>
